#include <optional>
#include <string>
#include <vector>

std::optional<std::string> safeJoin(const std::string& base, const std::string& relative)
{
    if (relative.empty()) return std::nullopt;
    if (relative[0] == '\\' || relative[0] == '/') return std::nullopt;     // rooted
    if (relative.find(':') != std::string::npos) return std::nullopt;       // drive letter or stream

    // Split on both separators, keeping empty components so they can be refused.
    std::vector<std::string> components{ "" };
    for (const char c : relative)
    {
        if (c == '\\' || c == '/') components.emplace_back();
        else components.back() += c;
    }

    std::vector<std::string> parts;
    for (const std::string& c : components)
    {
        if (c.empty()) return std::nullopt;                                 // "a//b" or a trailing separator
        if (c == ".") continue;
        if (c == "..") return std::nullopt;
        if (c.back() == ' ' || c.back() == '.') return std::nullopt;        // Windows would strip it
        parts.push_back(c);
    }

    std::string out{ base };
    for (const std::string& p : parts) out += "\\" + p;
    return out;
}

unitTests:
const std::string base{ "C:\\Game\\mods\\lantern" };
TEST("an ordinary file") { CHECK_EQ(*safeJoin(base, "textures/light.png"), std::string("C:\\Game\\mods\\lantern\\textures\\light.png")); }
TEST("backslashes too") { CHECK_EQ(*safeJoin(base, "data\\items.ini"), std::string("C:\\Game\\mods\\lantern\\data\\items.ini")); }
TEST("dot components are skipped") { CHECK_EQ(*safeJoin(base, "./data/./items.ini"), std::string("C:\\Game\\mods\\lantern\\data\\items.ini")); CHECK_EQ(*safeJoin(base, "."), base); }
TEST("parent directories are refused") { CHECK(!safeJoin(base, "../../saves/a.sav").has_value()); CHECK(!safeJoin(base, "data/../../x").has_value()); CHECK(!safeJoin(base, "..").has_value()); }
TEST("absolute paths are refused") { CHECK(!safeJoin(base, "C:\\Windows\\win.ini").has_value()); CHECK(!safeJoin(base, "\\Windows").has_value()); CHECK(!safeJoin(base, "/etc").has_value()); }
TEST("streams are refused") { CHECK(!safeJoin(base, "file.txt:hidden").has_value()); }
TEST("trailing dots and spaces are refused") { CHECK(!safeJoin(base, "secret.txt.").has_value()); CHECK(!safeJoin(base, "folder /a").has_value()); }
TEST("empty components are refused") { CHECK(!safeJoin(base, "a//b").has_value()); CHECK(!safeJoin(base, "").has_value()); }

